using System;using System.Linq;using System.IO;using System.Collections.Generic;using HarborCity;using HarborCity.RoadCore;
static class CityDepotLaneRoutingChecks {
 static int checks,different;static void Check(bool x,string m){checks++;if(!x)throw new Exception(m);}
 static void Compare(Network n,List<long> old,List<long> path,double os,double oe,double s,double e){Check((old==null)==(path==null),"Reachability mismatch");if(old==null)return;n.ValidateRoute(path);double a=new DispatchBlueprint(n,old,os,oe).seconds,b=new DispatchBlueprint(n,path,s,e).seconds;Check(Math.Abs(a-b)<=1e-9*Math.Max(1,Math.Abs(a)),"Shortest cost mismatch "+a+" / "+b);if(!old.SequenceEqual(path)||os!=s||oe!=e)different++;}
 static void Main(){var w=new World();var ids=new int[4,4];for(int z=0;z<4;z++)for(int x=0;x<4;x++)ids[x,z]=w.AddJunction(new Point(x*25,2,z*25));for(int z=0;z<4;z++)for(int x=0;x<4;x++){if(x<3)w.AddRoad(ids[x,z],ids[x+1,z],new[]{w.JunctionPosition(ids[x,z]),w.JunctionPosition(ids[x+1,z])},lanes:2);if(z<3)w.AddRoad(ids[x,z],ids[x,z+1],new[]{w.JunctionPosition(ids[x,z]),w.JunctionPosition(ids[x,z+1])},oneWay:x%2==1,lanes:2);}
 var lanes=w.Network.Drivables.Where(d=>!d.IsConnection).ToArray();var accesses=lanes.Select((d,i)=>new RoadAccess{endpoint=i+1,lane=d.Id,distance=d.StartDistance+d.TravelLength*(.15+(i%7)*.1)}).ToArray();foreach(var a in accesses)w.RegisterAccess(a.endpoint,a.lane,a.distance);
 foreach(var depot in accesses.Take(12))foreach(var target in accesses){var old=AccessRouting.Find(w.Network,depot,target,true,out double os,out double oe);Check(w.DepotRoutes.TryFind(w,depot.endpoint,depot,target,false,out var path,out double s,out double e),"No tree");Compare(w.Network,old,path,os,oe,s,e);var prior=path?.ToArray();w.DepotRoutes.TryFind(w,depot.endpoint,depot,target,false,out path,out s,out e);Check(prior==null?path==null:prior.SequenceEqual(path),"Warm changed route");old=AccessRouting.FromLane(w.Network,target.lane,target.distance,depot,true,out oe);Check(w.DepotRoutes.TryFind(w,depot.endpoint,depot,target,true,out path,out s,out e),"No reverse tree");Compare(w.Network,old,path,target.distance,oe,s,e);}
 Console.WriteLine("PASS "+checks+" lane-tree checks; equal-cost different route choices="+different+"; trees="+w.DepotRoutes.Count+" bytes="+w.DepotRoutes.ReservedTreeBytes);
 }
}
